INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-charlieapprovalguardwebm-543b5ed0', NULL, 'charlie_approval_guard.webm', '`charlie_approval_guard` is a system designed to manage and validate approval workflows within an automated environment. The provided documentation serves as visual proof of its functionality, demonstrating the system''s performance through real-world automated validation scenarios. Ultimately, the tool functions as a core component for End-to-End (E2E) Model-Based Testing (MBT), ensuring that approval processes are verified accurately and reliably.', 7, 'charlie_approval_guard.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/charlie_approval_guard.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-27 00:13:58+0000', '2026-05-27 00:13:58+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-davidrbacmatrixwebm-ba75f26d', NULL, 'david_rbac_matrix.webm', '**david_rbac_matrix** is a specialized tool designed for automated validation within the system''s role-based access control (RBAC) framework. It executes end-to-end (E2E) model-based testing (MBT) to verify that access permissions and user roles function as expected. The tool provides visual, documented evidence of these automated processes, ensuring system security and compliance through objective verification.', 7, 'david_rbac_matrix.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/david_rbac_matrix.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-27 00:29:53+0000', '2026-05-27 00:29:53+0000') ON CONFLICT (source_id) DO NOTHING;
